new file mode 100644
index 0000000..a8d19f9
--- /dev/null
+++ b/src/log-worker.ts
@@ -0,0 +1,26 @@
+import { parentPort } from "worker_threads";
+
+const queue: string[] = [];
+let flushing = false;
+
+const flush = async (): Promise<void> => {
+  if (flushing || queue.length === 0) return;
+  flushing = true;
+
+  const batch = queue.splice(0, queue.length);
+  await Promise.all(batch.map((msg) => writeAsync(msg)));
+
+  flushing = false;
+  if (queue.length > 0) flush();
+};
+
+const writeAsync = (msg: string): Promise<void> => {
+  return new Promise((resolve) => {
+    process.stdout.write(msg, () => resolve());
+  });
+};
+
+parentPort?.on("message", (msg: string) => {
+  queue.push(msg);
+  flush();
+});
diff --git a/src/log.ts b/src/log.ts
index 4892c8b..c62f111 100644
--- a/src/log.ts
